class GenericDuOperations(GenericBts):
    """Base keywords for eNB and gNB"""

    def __init__(self, bts_type):
        """
        Constructor of GenericBbbu class.
        :param bts_type: GNB|ENB
        :return: None
        """
        super(GenericDuOperations, self).__init__(bts_type=bts_type)
        self.uptime = {}

    @login_logout
    def reset_bts(self, bts_id=0, wait_for_reconnection=True, du_id=0):
        """
        Reset BTS and wait for reconnection.

        :param bts_id:int, BTS id - related to Test Line configuration.
        :param wait_for_reconnection:bool, flag which define if admin api will wait for reconnection to bts.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        self.admin.reset_site(connection=self.rest_alias.format(bts_id, du_id),
                              wait_for_reconnection=wait_for_reconnection,
                              timeout=1200)

    @login_logout
    def power_reset_bts(self, bts_id=0, du_id=0, reset_with_snapshot=False, wait_for_reconnection=False,
                        cold_reset_secondary_core_via_backplane=False, graceful_cell_shutdown=False, timeout=1200):
        """
        Power reset procedure introduced in CB007040 feature

        :param bts_id:int, BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param reset_with_snapshot:bool, Perform reset with snapshot collection
        :param wait_for_reconnection:bool, flag which define if admin api will wait for reconnection to bts.
        :param cold_reset_secondary_core_via_backplane:bool, Perform operation with cold reset secondary core via
        back plane
        :param graceful_cell_shutdown:bool, Perform reset procedure with graceful cell shutdown.
        :param timeout:int, timeout for operation
        :return: None
        """
        self.admin.power_reset(connection=self.rest_alias.format(bts_id, du_id),
                               reset_with_snapshot=reset_with_snapshot,
                               wait_for_reconnection=wait_for_reconnection,
                               cold_reset_secondary_core_via_backplane=cold_reset_secondary_core_via_backplane,
                               graceful_cell_shutdown=graceful_cell_shutdown, timeout=timeout)

