    def get_configured_rats(self, bts_id=0, du_id=0, timeout=60):
        """
        Get list of RATs configured on BTS

        :param bts_id:int, BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for operation
        :return: list of RATS, available values: NR, LTE, WCDMA, GSM
        """
        bts_info = self.get_bts_info(bts_id=bts_id, du_id=du_id, timeout=timeout)
        all_rats_status = bts_info['ratState']
        logging.debug(f'All RATs statuses: {all_rats_status}')
        rats = [rat for rat, status in all_rats_status.items() if status != 'NO_CELLS']
        logging.debug(f'Configured RATs: {rats}')
        return rats

    @login_logout
    def verify_rat_is_blocked(self, rat, bts_id=0, du_id=0, timeout=60):
        """
        Verify if given RAT is blocked.

        :param rat:string, RAT to verify - NR, LTE, WCDMA, GSM
        :param bts_id:int, BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for operation
        :raises: ValueError if status is not blocked
        :return: None
        """
        rat_blocking_state = self._get_rat_blocking_state(rat=rat, bts_id=bts_id, du_id=du_id, timeout=timeout)
        if rat_blocking_state != 'blocked':
            raise ValueError(f'Wrong rat={rat} blockingState: should be blocked but is {rat_blocking_state}')

