    def smods_power_on(self, cu_ids, bts_id=0, du_id=0, confirm=True, confirmation_delay=5, check_status_before=False):
        """
        Power on smods using power switch.
        :param cu_ids:list, CUs id - related to Test Line configuration, required.
        :param bts_id:int, BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param confirm: if true set value will be checked afterwards and if it is not set the exception is raised
        :param confirmation_delay: time in seconds
        :param check_status_before: check status of PDU port before power ON - and if ON skip executing power on
        :return: None
        """

        self._smods_pdu_on_off(operation="ON", cu_ids=cu_ids, bts_id=bts_id, du_id=du_id,
                               confirm=confirm, confirmation_delay=confirmation_delay,
                               check_status_before=check_status_before)

    def _smods_pdu_on_off(self, operation, cu_ids, bts_id=0, du_id=0, confirm=True, confirmation_delay=5,
                          check_status_before=False):

        obj_pdu = pdu()
        pdus = self._setup_all_smod_pdus(obj_pdu, cu_ids, bts_id, du_id)
        ports_power_on_before = self._perform_pdu_operation_if_needed(check_status_before, operation,
                                                                      pdus, bts_id, obj_pdu)
        self._perform_confirmation_if_needed(confirm, operation, confirmation_delay, pdus, ports_power_on_before,
                                             bts_id, obj_pdu)

        for pdu_alias in pdus:
            obj_pdu.teardown_pdu(pdu_device=pdu_alias)

    def _setup_all_smod_pdus(self, obj_pdu, cu_ids, bts_id, du_id):
        pdus = {}
        for cu_id in cu_ids:
            pdu_port = tl_config.get_bts_pdu_port(bts_id=bts_id, du_id=du_id, common_unit_id=cu_id,
                                                  bts_type=self.bts_type)
            pdu_alias, port_nr = self._setup_pdu(obj_pdu, pdu_port, already_setup_pdus=pdus)
            if pdu_alias not in pdus:
                pdus[pdu_alias] = []
            pdus[pdu_alias].append(port_nr)
        return pdus

    def _perform_pdu_operation_if_needed(self, check_status_before, operation, pdus, bts_id, obj_pdu):
        ports_power_on_before = {}
        operation = operation.upper()
        operation_method = obj_pdu.power_on if operation == "ON" else obj_pdu.power_off
        for pdu_alias in pdus:
            for port_nr in pdus[pdu_alias]:
                if check_status_before:
                    port_status = try_perform_operation_on_pdu(operation=obj_pdu.get_port_status,
                                                               port=port_nr,
                                                               pdu_device=pdu_alias)
                    logging.debug(f"[{self.bts_type}{bts_id}] Status of port {port_nr} before change: {port_status}")
                    if port_status.upper() == operation:
                        msg = f"[{self.bts_type}{bts_id}] Already {operation} - Skipping power {operation} procedure"
                        logging.info(msg)
                        if pdu_alias not in ports_power_on_before:
                            ports_power_on_before[pdu_alias] = []
                        ports_power_on_before[pdu_alias].append(port_nr)
                        continue
                try_perform_operation_on_pdu(operation=operation_method, port=port_nr, pdu_device=pdu_alias)
        return ports_power_on_before

    def _perform_confirmation_if_needed(self, confirm, operation, confirmation_delay, pdus, ports_power_on_before,
                                        bts_id, obj_pdu):
        operation = operation.upper()
        if confirm and pdus != ports_power_on_before:
            time.sleep(int(confirmation_delay))
            for pdu_alias in pdus:
                for port_nr in pdus[pdu_alias]:
                    if ports_power_on_before.get(pdu_alias) and port_nr in ports_power_on_before[pdu_alias]:
                        continue
                    port_status = try_perform_operation_on_pdu(operation=obj_pdu.get_port_status,
                                                               port=port_nr,
                                                               pdu_device=pdu_alias)
                    if port_status.upper() == operation:
                        logging.info(f"[{self.bts_type}{bts_id}] Port {port_nr} powered {operation}")
                    else:
                        raise WrongPduStatus(f"[{self.bts_type}{bts_id}] Port {port_nr} is NOT {operation}")

    def smods_power_off(self, cu_ids, bts_id=0, du_id=0, confirm=True, confirmation_delay=5,
                        check_status_before=False):
        """
        Power off smods using power switch.
        :param cu_ids:list, CUs id - related to Test Line configuration, required.
        :param bts_id:int, BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param confirm: if true set value will be checked afterwards and if it is not set the exception is raised
        :param confirmation_delay: time in seconds
        :param check_status_before: check status of PDU port before power OFF - and if OFF skip executing power off
        :return: None
        """
        self._smods_pdu_on_off(operation="OFF", cu_ids=cu_ids, bts_id=bts_id, du_id=du_id,
                               confirm=confirm, confirmation_delay=confirmation_delay,
                               check_status_before=check_status_before)

    def smods_power_reset(self, cu_ids, bts_id=0, du_id=0, confirm=True, confirmation_delay=5, off_on_delay=10):
        """
        Power reset SMODs using power switch.
        :param cu_ids:list, CUs id - related to Test Line configuration, required.
        :param bts_id:int, BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param confirm: if true set value will be checked afterwards and if it is not set the exception is raised
        :param confirmation_delay: time in seconds
        :param off_on_delay: delay between power off and power on
        :return: None
        """

        obj_pdu = pdu()
        pdus = self._setup_all_smod_pdus(obj_pdu, cu_ids, bts_id, du_id)
        for pdu_alias in pdus:
            ports = (port_nr for port_nr in pdus[pdu_alias])
            try_perform_operation_on_pdu(operation=obj_pdu.reset_ports, pdu_device=pdu_alias,
                                         ports=ports, time_interval=off_on_delay)
        self._perform_confirmation_if_needed(confirm, "ON", confirmation_delay, pdus, {},
                                             bts_id, obj_pdu)
        for pdu_alias in pdus:
            obj_pdu.teardown_pdu(pdu_device=pdu_alias)

    def bts_power_on(self, bts_id=0, du_id=0, confirm=True, confirmation_delay=5, check_status_before=False):
        """
        Power on BTS using power switch.
        :param bts_id:int, BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param confirm: if true set value will be checked afterwards and if it is not set the exception is raised
        :param confirmation_delay: time in seconds
        :param check_status_before: check status of PDU port before power ON - and if ON skip executing power on
        :return: None
        """
        cu_count = tl_config.get_count_of_common_units(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        cu_ids = list(range(cu_count))
        self.smods_power_on(cu_ids=cu_ids, bts_id=bts_id, du_id=du_id, confirm=confirm,
                            confirmation_delay=confirmation_delay, check_status_before=check_status_before)

