    @login_logout
    def check_bts_sw_version(self, sw_version, partition="active", bts_id=0, du_id=0):
        """
        Verify active bts version on given partition
        :param sw_version: expected sw_version
        :param partition: partition of BTS to be verified, possible values: "active", "passive"
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: bool, True if sw_versions match, False if not match
        """
        bts_version = self.admin.get_software_info(
            connection=self.rest_alias.format(bts_id, du_id))["{} SW version".format(partition.capitalize())]
        simplified_bts_version = SwVersionFactory().create_sw_version(bts_version).simplified
        if simplified_bts_version in sw_version.replace("_", "."):
            return True
        return False

    @log_as_robot_keyword
    def verify_active_sw_version(self, sw_version, bts_id=0, du_id=0):
        """
        Verify active bts version
        :param sw_version: expected sw_version
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        :raises: ValueError if active sw_version is not as expected
        """
        wanted_sw_version = SwVersionFactory().create_sw_version(sw_version)
        current_sw_version = SwVersionFactory().create_sw_version(self.get_bts_sw_version(bts_id=bts_id, du_id=du_id))
        if wanted_sw_version != current_sw_version:
            raise ValueError(f"Active SW version: {current_sw_version.raw} is not "
                             f"as expected: {wanted_sw_version.raw}")
        logging.info(f"Active SW version: {current_sw_version.raw} is as expected: {wanted_sw_version.raw}")

    @log_as_robot_keyword
    def wait_until_sw_activated(self, sw_version, bts_id=0, du_id=0, interval=30, timeout=300):
        """
        Wait until given sw_version is active
        :param sw_version: expected sw_version
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param interval: interval between checks
        :param timeout: timeout for operation
        :return: None
        """
        wait_params = {
            'func': self.verify_active_sw_version,
            'exception_to_catch': (ValueError, DataNotAvailable),
            'interval': interval,
            'timeout': timeout,
            'sw_version': sw_version,
            'bts_id': bts_id,
            'du_id': du_id
        }
        try:
            return wait_till_succeeds(**wait_params)
        except AdminApiException as e:
            logging.debug(f"API exception occurred: {get_formatted_traceback(e)}")
            self.connect(bts_id=bts_id, du_id=du_id, force=True, timeout=120, reconnect_attempts=5,
                         use_lmp_if_mplane_unreachable=False)

        wait_till_succeeds(**wait_params)

    @login_logout
    def is_sw_update_in_progress(self, bts_id=0, du_id=0):
        """
        Check if SW update is in progress.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: bool, True if SW update is in progress, False if not
        """
        swm_dist_name_template = '/MRBTS-1/RAT-1/SWM-{}'
        for swm_id in [1, 4]:
            swm_dist_name = swm_dist_name_template.format(swm_id)
            logging.debug(f"Checking if SW update is in progress for: {swm_dist_name}")
            try:
                results = self.admin.get_parameters(dist_name=swm_dist_name,
                                                    connection=self.rest_alias.format(bts_id, du_id))
                sw_status = results['stateInfo']['usageState']
                logging.debug(f"Usage State for {swm_dist_name} is: {sw_status}")
                if sw_status.lower() == 'busy':
                    logging.debug("SW update is in progress")
                    return True
                logging.debug(f"SW update is possible for {swm_dist_name}")
            except AdminApiProcedureFailureException as e:
                if "Object not found" in str(e):
                    logging.debug(f"{swm_dist_name} object not exist - skipping")
        return False

    @login_logout
    def is_cplane_busy(self, bts_id=0, du_id=0):
        """
        Check if any CPLANE managed object is in Busy usage state.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: bool, True if any CPLANE usageState is Busy, otherwise False
        """
        cplane_objects = self.admin.get_managed_objects(connection=self.rest_alias.format(bts_id, du_id),
                                                        class_name='CPLANE')
        for cplane_object in cplane_objects:
            dist_name = cplane_object.get('distName')
            usage_state = cplane_object.get('parameters', {}).get('stateInfo', {}).get('usageState')
            logging.debug(f"Usage State for {dist_name} is: {usage_state}")
            if isinstance(usage_state, str) and usage_state.lower() == 'busy':
                return True
        return False

    def wait_till_cplane_is_not_busy(self, bts_id=0, du_id=0, check_interval=15, timeout=300):
        """
        Wait until CPLANE usage state is not Busy.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param check_interval: interval between checks
        :param timeout: timeout for operation
        :return: None
        """
        check_interval = time_to_seconds(time=check_interval)
        end_time = time.monotonic() + time_to_seconds(time=timeout)
        while time.monotonic() <= end_time:
            time.sleep(check_interval)
            if not self.is_cplane_busy(bts_id=bts_id, du_id=du_id):
                break
        else:
            raise TimeoutError(f"CPLANE is still Busy after {timeout} seconds")

    def wait_till_sw_update_is_possible(self, bts_id=0, du_id=0, check_interval=60, timeout=1800):
        """
        Wait until SW update is possible.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for operation
        :return: None
        """
        check_interval = time_to_seconds(time=check_interval)
        end_time = time.monotonic() + time_to_seconds(time=timeout)
        while time.monotonic() <= end_time:
            time.sleep(check_interval)
            if not self.is_sw_update_in_progress(bts_id=bts_id, du_id=du_id):
                break
        else:
            raise SwUpdateInProgress(f"SW update is still in progress after {timeout} seconds")

    @staticmethod
    def _setup_pdu(obj_pdu, pdu_port, timeout=90, already_setup_pdus=None):
        """
        This method was created to keep backward compatibility - will be removed in future.
        :return: port_nr
        """

        if hasattr(pdu_port, 'addr'):
            logging.warning("Wrong configuration of pdu_port - please use PduPort class. "
                            "Your test will be working but support for wrong configuration "
                            "will be removed in the future")
            alias = pdu_port.addr
            if not (already_setup_pdus is not None and alias in already_setup_pdus):
                obj_pdu.setup_pdu(model=pdu_port, host=pdu_port.addr, login=pdu_port.login,
                                  password=pdu_port.password, timeout=timeout, alias=alias)
            port_nr = pdu_port.port_numbers[0]
        else:
            bts_pdu = pdu_port.pdu
            alias = bts_pdu.addr
            if not (already_setup_pdus is not None and alias in already_setup_pdus):
                obj_pdu.setup_pdu(model=bts_pdu, timeout=timeout, alias=alias)
            port_nr = pdu_port.port_no

        return alias, port_nr

