    def check_statuses_on_gnss(self, bts_id=0, du_id=0, gnss_id=1):
        """
        Check statuses on GNSS
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[].
        :param gnss_id: GNSS id
        :return: GNSS status
        """
        gnss_status_check = self.admin.get_gnsses_statuses(connection=self.rest_alias.format(bts_id, du_id))
        _gnss_status = gnss_status_check["GNSSE_R-" + str(gnss_id)]
        gnss_status = {"availabilityStatus": _gnss_status.get("availabilityStatus"),
                       "operationalState": _gnss_status.get("operationalState"),
                       "administrativeState": _gnss_status.get("administrativeState")}

        return gnss_status

    def verify_statuses_on_gnss(self, bts_id=0, du_id=0, gnss_id=1, operational_state="enabled",
                                availability_status="online", administrative_state="unlocked"):
        """
        Verify statuses on GNSS
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id:   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[].
        :param gnss_id: GNSS id
        :param operational_state:    Operational state of bts.
        :param availability_status:    Availability status of bts.
        :param administrative_state:    Administrative state of bts.
        :return: None
        """
        expected_statuses = {
            "availabilityStatus": availability_status.lower(),
            "operationalState": operational_state.lower(),
            "administrativeState": administrative_state.lower()
        }
        try:
            gnss_statuses = self.check_statuses_on_gnss(bts_id=bts_id, du_id=du_id, gnss_id=gnss_id)
            unify_statuses(gnss_statuses, required_keys=expected_statuses.keys())
            for status in expected_statuses:
                if expected_statuses[status] != gnss_statuses[status]:
                    logging.info("Expected status {}, actual status {}".format(expected_statuses[status],
                                                                               gnss_statuses[status]))
                    raise InvalidStatuses
        except KeyError as e:
            raise DataNotAvailable("Cannot get expected status info: {}".format(repr(e)))

