    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def _get_current_bts_uptime_value(self, bts_id=0, du_id=0):
        """
        Get uptime value and timestamp from BTS [in seconds]
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: current BTS uptime [seconds]
        """
        try:
            gnb = DeviceFactory.get_device(name=self.ssh_alias.format(bts_id, du_id))
            gnb.goto_state("FCT")
        except DeviceChangeStateFailure as err:
            MolerTest.error("Couldn't correctly establish connection to FCT BTS\n{}".format(repr(err)))
            MolerTest.steps_end()
        cat_cmd = gnb.get_cmd(cmd_name="cat", cmd_params={'path': '/proc/uptime'})
        uptime = {'timestamp': int(float(time.time())), 'value': int(float(cat_cmd()['LINES'][0].split(" ")[0]))}
        logging.info("Current uptime on BTS: {}".format(uptime))
        MolerTest.steps_end()
        return uptime

    def wait_for_site_to_be_onair(self, bts_id=0, timeout=900, interval=10, du_id=0):
        """
        Wait for site to be onair until timeout
        :param bts_id:  BTS id - related to Test Line configuration.
        :param timeout:  Time in seconds to wait for site to go onair
        :param interval:  time in seconds between each status check
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        start_time = time.time()
        end_time = start_time + time_to_seconds(time=timeout)
        interval_in_seconds = time_to_seconds(time=interval)
        while time.time() < end_time:
            try:
                self.verify_bts_is_onair(bts_id=bts_id, du_id=du_id)
                logging.info("Bts is 'OnAir")
                break
            except IncorrectStatuses:
                time.sleep(interval_in_seconds)
            except (AdminApiConnectionClosedException, AdminApiProcedureFailureException,
                    AdminApiProcedureTimeoutException):
                time.sleep(interval_in_seconds)
        else:
            raise SiteNotOnAir("Timeout passed. Bts status in not onAir")

    def wait_for_site_to_be_available(self, bts_id=0, timeout=180, interval=10, du_id=0):
        """
        Wait for site to be available
        :param bts_id:  BTS id - related to Test Line configuration.
        :param timeout:  Time in seconds to wait for site to be available
        :param interval:  time in seconds between each status check
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        start_time = time.time()
        while time.time() < start_time + time_to_seconds(time=timeout):
            try:
                self.verify_site_availability(bts_id=bts_id, timeout=30, du_id=du_id)
                logging.info("Site is available.")
                break
            except IncorrectParameterValue:
                time.sleep(time_to_seconds(time=interval))
            except (AdminApiConnectionClosedException, AdminApiProcedureFailureException,
                    AdminApiProcedureTimeoutException, AdminApiTerminatedException, AdminApiNoResponseException):
                time.sleep(time_to_seconds(time=interval))
            except Exception as ex:
                logging.info("Site is not available because: {}".format(repr(ex)))
                time.sleep(time_to_seconds(time=interval))
        else:
            raise SiteNotAvailable("Timeout passed. Bts is not available")

