    def wait_unitl_connection_via_admin_is_possible(self, bts_id=0, timeout=180, interval=10, du_id=0):
        """
        Wait until connection with BTS via admin CLI is possible
        :param bts_id:  BTS id - related to Test Line configuration.
        :param timeout:  Time in seconds to wait until connection is possible
        :param interval:  time in seconds between each status check
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        start_time = time.time()
        while time.time() < start_time + time_to_seconds(time=timeout):
            try:
                self.connect(bts_id=bts_id, du_id=du_id)
                logging.info("Connection with BTS is possible via Admin Api")
                self.disconnect(bts_id=bts_id, du_id=du_id)
                break
            except (AdminApiConnectionClosedException, AdminApiProcedureFailureException,
                    AdminApiProcedureTimeoutException, AdminApiTerminatedException, AdminApiNoResponseException):
                logging.info("Connection with BTS is not possible via Admin Api")
                time.sleep(time_to_seconds(time=interval))
            except Exception as e:
                logging.info("Connection with BTS is not possible via Admin Api because there occurs following error: "
                             "{}".format(repr(e)))
        else:
            raise ConnectionViaAdminNotPossible("Timeout passed. Connection with BTS is not possible via Admin Api")

