    def save_bts_uptime(self, bts_id=0, du_id=0):
        """
        Set uptime value and timestamp to current BTS value [in seconds]
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        bts_name = self.ssh_alias.format(bts_id, du_id)
        self.uptime[bts_name] = self._get_current_bts_uptime_value(bts_id=bts_id, du_id=du_id)

    def verify_no_bts_reboot_since_last_saved_uptime(self, bts_id=0, du_id=0):
        """
        Verify that BTS has not been rebooted by comparison of current uptime value with the previous one set.
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        bts_name = self.ssh_alias.format(bts_id, du_id)
        current_uptime = self._get_current_bts_uptime_value(bts_id, du_id)
        try:
            last_uptime = self.uptime[bts_name]
        except KeyError:
            raise IncorrectParameterValue("Uptime value not set on bts, save uptime before using this method.")
        last_boot_time = last_uptime['timestamp'] - last_uptime['value']
        current_boot_time = current_uptime['timestamp'] - current_uptime['value']
        logging.debug("Last boot time: {}, current boot time: {}".format(last_boot_time, current_boot_time))
        if (current_boot_time - last_boot_time) > 5:
            raise UnexpectedBtsResetOccurred(
                "BTS has been rebooted, current uptime:{} < {}".format(current_uptime, last_uptime))
        logging.info("BTS current uptime: {}[seconds], last uptime: {}".format(current_uptime, last_uptime))

    @login_logout
    def _verify_common_unit_state(self, bts_id=0, ops="enabled", avs="online", admin_state="unlocked",
                                  proc_state="configured", timeout=30, du_id=0):
        """
        Gets ASIK(Common Unit) state and verifies against the state that tester demands

        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param ops: operationalState of Common Unit
        :param avs: availabilityStatus of Common Unit
        :param admin_state: administrativeState of Common Unit
        :param proc_state: proceduralState of Common Unit
        :param timeout: timeout for positive procedure result
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        system_module_info = self.get_bts_info(bts_id=bts_id, du_id=du_id, timeout=timeout)['systemModules']
        for system in system_module_info:
            system_status = system['status']
            unify_statuses(system_status, required_keys=['availabilityStatus', 'operationalState',
                                                         'proceduralStatus', 'administrativeState'])
            assert system_status['operationalState'] == ops.lower(), \
                "Operational state: {} != {}".format(system_status['operationalState'], ops)
            assert system_status['availabilityStatus'] == avs.lower(), \
                "Availability status: {} != {}".format(system_status['availabilityStatus'], avs)
            assert system_status['administrativeState'] == admin_state.lower(), \
                "Administrative state: {} != {}".format(system_status['administrativeState'], admin_state)
            assert system_status['proceduralStatus'] == proc_state.lower(), \
                "Procedural state: {} != {}".format(system_status['proceduralStatus'], proc_state)
        logging.info("ASIK(Common Unit) states are as declared")

    @login_logout
    def _verify_capacity_unit_state(self, bts_id=0, ops="enabled", avs="online", admin_state="unlocked",
                                    proc_state="configured", skip_not_installed=False, timeout=30, du_id=0,
                                    bbmod_id=None):
        """
        Get Capacity Unit state and verify against the state that tester demands

        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param ops: operationalState of Common Unit
        :param avs: availabilityStatus of Common Unit
        :param admin_state: administrativeState of Common Unit
        :param proc_state: proceduralStatus of Common Unit
        :param timeout: timeout for positive procedure result
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param bbmod_id: id of BBMOD managedObjet; if None all BBMODs are checked
        :return: None
        """
        bbmods_info = self.get_bts_info(bts_id=bts_id, du_id=du_id, timeout=timeout)['basebandModules']
        bbmods_status = {}
        logging.debug("BBMOD info: {}".format(bbmods_info))
        for bbmod_info in bbmods_info:
            _bbmod_id = re.search(r'BBMOD_R-(\d+)', bbmod_info['id']['runtime']).group(1)
            bbmods_status[int(_bbmod_id)] = bbmod_info['status']

        if bbmod_id is not None:
            bbmod_id = int(bbmod_id)
            if bbmod_id not in bbmods_status.keys():
                raise IncorrectParameterValue('Given bbmod_id value ({}) is incorrect'.format(bbmod_id))
            else:
                bbmod_status = bbmods_status[bbmod_id]
                self._check_bbmod_statuses(bbmod_id=bbmod_id, status_dict=bbmod_status, ops=ops, avs=avs,
                                           admin_state=admin_state, proc_state=proc_state)
        else:
            for bbmod_id in bbmods_status.keys():
                bbmod_status = bbmods_status[bbmod_id]
                if skip_not_installed and bbmod_status['proceduralStatus'] == 'not initialized':
                    logging.debug("Skipping not installed BBMOD-{}".format(bbmod_id))
                    continue
                self._check_bbmod_statuses(bbmod_id=bbmod_id, status_dict=bbmod_status, ops=ops, avs=avs,
                                           admin_state=admin_state, proc_state=proc_state)

    def _check_bbmod_statuses(self, bbmod_id, status_dict, ops, avs, admin_state, proc_state):
        """
        :param ops: operationalState of Common Unit
        :param avs: availabilityStatus of Common Unit
        :param admin_state: administrativeState of Common Unit
        :param proc_state: proceduralStatus of Common Unit
        :param status_dict: dict where keys are status names and values are their current values
        :return: None
        """
        logging.info("Checking statuses for BBMOD-{}".format(bbmod_id))
        unify_statuses(status_dict, required_keys=['availabilityStatus', 'operationalState',
                                                   'proceduralStatus', 'administrativeState'])
        assert status_dict['operationalState'] == ops.lower(), \
            "Operational state: {} != {}".format(status_dict['operationalState'], ops)
        assert status_dict['availabilityStatus'] == avs.lower(), \
            "Availability status: {} != {}".format(status_dict['availabilityStatus'], avs)
        assert status_dict['administrativeState'] == admin_state.lower(), \
            "Administrative state: {} != {}".format(status_dict['administrativeState'], admin_state)
        assert status_dict['proceduralStatus'] == proc_state.lower(), \
            "Procedural state: {} != {}".format(status_dict['proceduralStatus'], proc_state)
        logging.info("BBMOD-{} states are as declared".format(bbmod_id))

    @load_moler_configuration_from_tl()
    def _verify_virtual_nodes_running(self, bts_id=0, du_id=0):
        """
        Verify that all node status are in RUNNING state

        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        bts = DeviceFactory.get_device(name=self.ssh_alias.format(bts_id, du_id))
        bts.goto_state('FCT')
        lxcls_cmd = bts.get_cmd(cmd_name='lxc_ls', cmd_params={'options': '-f'})
        all_nodes = lxcls_cmd()['RESULT']
        for node in all_nodes:
            assert node['State'] == 'RUNNING', "Node {} is not in running state".format(node)
        logging.info("All nodes are in RUNNING state")

