    @login_logout
    def verify_bts_states(self, bts_id=0, du_id=0, operational_state=None, procedural_state=None,
                          blocking_state=None):
        """
        Verify BTS states
        If you would like to omit checking certain state, please provide None value.
        You can also provide state as regex eg re.compile(r'onair|configured')

        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param operational_state:       expected cell operational state (enabled/disabled)
        :param procedural_state:        expected cell procedural state (onair)
        :param blocking_state:          expected cell blocking state (unblocked/blocked)
        :return: None
        """
        passed_args = copy(locals())
        var_key_mapping = {
            'operational_state': "operationalState",
            'procedural_state': "proceduralState",
            'blocking_state': "blockingState",
        }
        expected_statuses = {}
        for arg_name, arg_value in passed_args.items():
            if arg_name in var_key_mapping.keys() and arg_value is not None:
                expected_statuses[var_key_mapping[arg_name]] = arg_value

        if not expected_statuses:
            raise ValueError("Expected statuses are empty - please pass at least one of state to check")

        bts_statuses = self.admin.get_bts_statuses(connection=self.rest_alias.format(bts_id, du_id))
        unify_statuses(bts_statuses, required_keys=expected_statuses.keys())
        verify_statuses(expected_statuses=expected_statuses, received_statuses=bts_statuses)
        logging.info("All BTS states are as expected")

