    @login_logout
    def _get_sfp_data_from_bts(self, bts_id=0, du_id=0):
        """
        author:         Maciej Russek, maciej.russek@nokia.com
        maintainer:     Maciej Russek, maciej.russek@nokia.com
        Get SFP links data from BTS
        :param bts_id:      BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:            BTS internal SFP links database
        """
        return self.admin.get_sfp_links(connection=self.rest_alias.format(bts_id, du_id))

    def _check_if_sfp_data_is_correct(self, sfp_link_data):
        """
        author:         Maciej Russek, maciej.russek@nokia.com
        maintainer:     Maciej Russek, maciej.russek@nokia.com

        Check if all SFP parameters are present as readable data
        :return:        List with incorrect data if any exists
        """
        incorrect_data_list = []
        sfp_link_keys_and_values = list(return_all_key_paths_and_values_from_iterable(sfp_link_data))
        sfp_details = sfp_link_data['data']['linkPorts']
        for key_and_value in sfp_link_keys_and_values:
            try:
                if '?' in str(key_and_value[-1]):
                    incorrect_data_list.append([sfp_details, key_and_value])
            except UnicodeEncodeError:
                if '?' in str(key_and_value[-1].encode("utf-8")):
                    incorrect_data_list.append([sfp_details, key_and_value])

        return incorrect_data_list

    def _check_if_all_connected_sfp_data_is_correct(self, sfp_data):
        """
        author:         Maciej Russek, maciej.russek@nokia.com
        maintainer:     Maciej Russek, maciej.russek@nokia.com

        Check if any connected SFP link exists then if its parameters are present as readable data
        """
        incorrect_data_list = []
        try:
            connected_sfp_links = sfp_data['connected']
        except KeyError:
            raise NoConnectedSfp()

        for connected_sfp_link in connected_sfp_links:
            incorrect_data_list.extend(self._check_if_sfp_data_is_correct(connected_sfp_link))

        if incorrect_data_list:
            raise IncorrectSfpData(incorrect_data_list)

    def verify_sfp_data(self, bts_id=0, du_id=0):
        """
        author:         Maciej Russek, maciej.russek@nokia.com
        maintainer:     Maciej Russek, maciej.russek@nokia.com

        Get SFP links data from BTS then heck if all SFP parameters are present as readable data
        :param bts_id:      BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """
        bts_sfp_data = self._get_sfp_data_from_bts(bts_id, du_id)
        self._check_if_all_connected_sfp_data_is_correct(bts_sfp_data)

    def _verify_bts_is_in_state(self, state, bts_id=0, du_id=0):
        """
        Verify if bts is in specific operational state.
        :param state: operational state in which is bts;
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """

        state = str(state).lower()
        acceptable_states = ('onair', 'notcommissioned')
        assert state in acceptable_states
        bts_state = self._get_bts_state(bts_id, du_id)

        if bts_state != state:
            raise IncorrectParameterValue(
                "{} is not in {} state. Current unexpected state is: {}".format(bts_id, state, bts_state))
        else:
            logging.info("{} is {} as expected.".format(self.rest_alias.format(bts_id, du_id), state))

    @load_moler_configuration_from_tl()
    def upload_swconfig(self, sw_config_path, bts_id=0, du_id=0, cu_id=0, reboot_after_upload=False):
        """
        Copy a local swconfig file to /rom/ directory.
        :param sw_config_path: local path to swconfig.
        :param bts_id: BTS(gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cu_id: CU id(Control Unit) - id related to Test Line configuration - gnb.cu[]
        :param reboot_after_upload: reboot DU after upload
        """

        bts_name = self.ssh_cu_lmp_alias.format(bts_id, du_id, cu_id)
        if cu_id == 1:
            self._find_working_lmp_ip_address(bts_name)

        upload_files(local_dir=os.path.dirname(sw_config_path),
                     local_file=os.path.basename(sw_config_path),
                     remote_dir='/rom/',
                     device_name=bts_name,
                     new_file_name='swconfig.txt',
                     )

        if reboot_after_upload:
            bts = DeviceFactory.get_device(bts_name)
            reboot_cmd = bts.get_cmd(cmd_name='reboot')
            reboot_cmd()

    @staticmethod
    def _find_working_lmp_ip_address(bts_name):
        working_ip_address = None
        possible_secondary_lmp_ip_addresses = [
            '192.168.255.129',  # when not configured
            '192.168.255.119',  # when configured
            '192.168.255.7',    # when configured
        ]
        bts = DeviceFactory.get_device(bts_name, initial_state='PROXY_PC')
        current_lm_ip_address = bts.get_fct_address()
        if current_lm_ip_address not in possible_secondary_lmp_ip_addresses:
            possible_secondary_lmp_ip_addresses.insert(0, current_lm_ip_address)

        for address in possible_secondary_lmp_ip_addresses:
            logging.info(f"Ping LMP BTS ({address}) from Workstation")
            ping_cmd = bts.get_cmd(cmd_name="ping", cmd_params={'destination': address, 'options': '-c 7'})
            results = ping_cmd()

            logging.debug("Transmitted: {}".format(results['packets_transmitted']))
            logging.debug("Received: {}".format(results['packets_received']))
            logging.debug("Packed loss: {}%".format(results['packet_loss']))

            is_ip_working = False if results['packet_loss'] == 100 else True
            if is_ip_working:
                working_ip_address = address
                logging.info("Working IP address: {}".format(working_ip_address))
                break
        if working_ip_address is None:
            raise ValueError(f"No working LMP IP address found for {bts_name}")

        bts.set_fct_address(working_ip_address)
        bts.goto_state('FCT')
        bts.initial_state = 'FCT'
        return working_ip_address

