    @load_moler_configuration_from_tl()
    def _verify_if_flag_exists_in_swconfig(self, swconfig, flag, bts_id=0, du_id=0):
        """
        Verifies if flag exists in swconfig.txt

        :param swconfig:        Path to swconfig.txt file
        :param flag:            Flag which is verified
        :param bts_id:          BTS id - related to Test Line configuration
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:                Grepped dictionary
        """
        bts_name = self.ssh_alias.format(bts_id, du_id)
        bts = DeviceFactory.get_device(bts_name)
        grep_cmd = bts.get_cmd(cmd_name='grep',
                               cmd_params={
                                   'options': '{} {}'.format(flag, swconfig)
                               })
        return grep_cmd()['LINES']

    @load_moler_configuration_from_tl()
    def set_swconfig_flag(self, flag, value, reboot_after_set=False, swconfig='/rom/swconfig.txt', bts_id=0, du_id=0):
        """
        Set swconfig flag with given value

        :param flag:                String representation of hexadecimal value of the flag
        :param value:               Value to be set
        :param reboot_after_set:    Flag to reboot BTS after setting
        :param swconfig:            Path to swconfig.txt file
        :param bts_id:              BTS id - related to Test Line configuration
        :param du_id:               DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """

        bts_name = self.ssh_alias.format(bts_id, du_id)
        bts = DeviceFactory.get_device(bts_name)
        scripts = [r's/^{}=[0x]*[[:digit:]]*$/{}={}/g'.format(flag, flag, value)]

        if self._verify_if_flag_exists_in_swconfig(swconfig=swconfig, flag=flag):
            sed_cmd = bts.get_cmd(cmd_name='sed',
                                  cmd_params={
                                      'options': '-i',
                                      'scripts': scripts,
                                      'input_files': [swconfig]
                                  })
            sed_cmd()
        else:
            echo_cmd = bts.get_cmd(cmd_name='echo',
                                   cmd_params={
                                       'options': "{}={} >> {}".format(flag, value, swconfig),
                                   })
            echo_cmd()
        if reboot_after_set:
            reboot_cmd = bts.get_cmd(cmd_name='reboot')
            reboot_cmd()

    def _get_all_bbmod_ids(self, bts_id=0, du_id=0):
        """
        Get list of BBMOD ids based on RUNTIME dist name
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:            list of all available RUNTIME BBMOD unit IDs
        """
        bbmod_ids = []
        bts_info = self.admin.get_bts_info(connection=self.rest_alias.format(bts_id, du_id))
        for bbmod_info in bts_info['basebandModules']:
            dist_name = bbmod_info['id']['internal']
            match = re.search(r'(?P<BBMOD_ID>\d+)$', dist_name)
            if match:
                bbmod_id = match.group("BBMOD_ID")
                bbmod_ids.append(int(bbmod_id))

        return bbmod_ids

    def _get_runtime_bbmod_dist_name(self, bts_id=0, du_id=0, bbmod_id=1):
        """
        Get RUNTIME BBMOD dist_anme
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param bbmod_id:    RUNTIME BBMOD id
        :return:            RUNTIME dist_name
        """
        bts_info = self.admin.get_bts_info(connection=self.rest_alias.format(bts_id, du_id))
        for bbmod_info in bts_info['basebandModules']:
            dist_name = bbmod_info['id']['internal']
            match = re.search(r'-{}$'.format(bbmod_id), dist_name)
            if match:
                return dist_name

    def get_all_bbmod_ids_map(self, bts_id=0, du_id=0):
        """
        Extracts BBMODs runtime ids and configuration ids from bts_info and returns a dictionary
        mapping runtime id to configuration id.
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:  dict with BBMODs configuration and runtime ids, e.g:
        {'BBMOD-1': "BBMOD_R-1"}
        """
        bts_info = self.admin.get_bts_info(connection=self.rest_alias.format(bts_id, du_id))
        id_map = {}
        for bbmod in bts_info['basebandModules']:
            configuration_id = bbmod['id'].get('configuration').split('/')[-1]
            runtime_id = bbmod['id'].get('runtime').split('/')[-1]
            id_map[configuration_id] = runtime_id
        return id_map

