    @login_logout
    def verify_cablink_operational_state(self, cablink_id="all", expected_state="enabled",
                                         timeout=60, bts_id=0, du_id=0):
        """
        Verify if cablink operational state is enabled.
        :param cablink_id: cablink id from configuration to check. If "all" than all cablinks will be check
        :param expected_state: expected cablink state
        :param timeout: timeout for positive procedure result
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        cablinks_status = self.get_bts_info(bts_id=bts_id, du_id=du_id, timeout=timeout)['cables']
        if cablink_id == "all":
            wrong_status_cablinks = [cablink["id"]["configuration"] for cablink in cablinks_status
                                     if cablink["status"]["operationalState"] != expected_state]
            if wrong_status_cablinks:
                raise InvalidStatuses(f"CABLINKS: {wrong_status_cablinks} are NOT {expected_state}")
            logging.info(f"All CABLINKS are {expected_state} as expected")
        else:
            for cablink in cablinks_status:
                match = re.search(r'CABLINK-(\d+)', cablink["id"]["configuration"])
                if match and int(match.group(1)) == cablink_id:
                    if cablink["status"]["operationalState"] == expected_state:
                        logging.info(f"CABLINK-{cablink_id} is {expected_state} as expected")
                        return
                    raise InvalidStatuses(f"CABLINK: [{cablink['id']['configuration']}] is NOT {expected_state}")
            raise InvalidStatuses(f"CABLINK-{cablink_id} not found")

