    @login_logout
    def _get_all_sfp_lanes_for_radio_unit(self, radio_unit_id, radio_type, timeout=60, bts_id=0, du_id=0):
        re_rmod = re.compile(r"MRBTS-\d+/EQM-\d+/APEQM-\d+/{}-{}".format(radio_type.upper(), radio_unit_id))
        cablink_info = self.admin.get_parameter_by_class(class_name="CABLINK", timeout=int(timeout),
                                                         connection=self.rest_alias.format(bts_id, du_id))
        sfp_endpoints = []
        for cablink in cablink_info:
            param = cablink['parameters']
            if re.match(re_rmod, param['secondEndpointDN']):
                bbmod_sfp_info = self.admin.get_parameter_by_parent_distname(parent_dn=param['firstEndpointDN'],
                                                                             child_class_name='SFP',
                                                                             timeout=int(timeout),
                                                                             connection=self.rest_alias
                                                                             .format(bts_id, du_id))

                hw_port = "{}RF{}".format('Q_' if param['firstEndpointLabel'] == "QSFP" else '',
                                          param['firstEndpointPortId'])
                for sfp in bbmod_sfp_info:
                    if sfp['parameters']['hwPortId'] == hw_port:
                        sfp_endpoints.append(sfp['distName'])
        lane_info = self.admin.get_parameter_by_class(class_name="LANE", timeout=int(timeout),
                                                      connection=self.rest_alias.format(bts_id, du_id))
        return [lane['distName'] for lane in lane_info if lane['distName'].split("/LANE")[0] in sfp_endpoints]

    def _get_rat_blocking_state(self, rat, bts_id=0, du_id=0, timeout=60):
        params = self.admin.get_parameter_by_parent_distname(
            parent_dn=self.adjust_dist_name(dist_name='MRBTS-{}', bts_id=bts_id, du_id=du_id),
            connection=self.rest_alias.format(0, 0),
            timeout=timeout)
        if rat == 'GSM':
            rat_params = [item for item in params if item['distName'] == self.adjust_dist_name(
                dist_name=rat_distname_patterns[rat].bcf_dist_name, bts_id=bts_id, du_id=du_id)][0]
        else:
            rat_params = [item for item in params if item['distName'] == self.adjust_dist_name(
                dist_name=rat_distname_patterns[rat].bts_dist_name, bts_id=bts_id, du_id=du_id)][0]
        rat_blocking_state = rat_params['parameters']['blockingState'].lower()
        logging.debug(f'RAT={rat} blocking state: {rat_blocking_state}')
        return rat_blocking_state

