@six.add_metaclass(Singleton)
class EnbDuOperations(GenericDuOperations):
    """Class contains Base keywords for eNB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.
        """

        super(EnbDuOperations, self).__init__(bts_type=EnbDuOperations.bts_type)

    @login_logout
    def _get_bts_state(self, bts_id=0, du_id=0):
        return str(self.admin.get_mrbts_state(connection=self.rest_alias.format(bts_id, du_id))).lower()


@six.add_metaclass(Singleton)
class GnbDuOperations(GenericDuOperations):
    """Class contains Base keywords for gNB"""

    bts_type = 'GNB'

    def __init__(self):
        """
        Constructor of Gnb class.
        """
        super(GnbDuOperations, self).__init__(bts_type=GnbDuOperations.bts_type)

    @login_logout
    def _get_bts_state(self, bts_id=0, du_id=0):
        statuses = self.admin.get_bts_statuses(connection=self.rest_alias.format(bts_id, du_id))
        try:
            bts_state = statuses['proceduralState'].lower()
        except KeyError as e:
            raise DataNotAvailable(
                "Cannot get BTS from response. Response: {}. Error details: {}".format(statuses, repr(e)))

        return bts_state

    @login_logout
    def get_cu_type(self, gnb_id=0, du_id=0):
        """
        Get the gNB CU Type i.e NSA or SA

        :param gnb_id: gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: gNB CU Type
        :rtype: str
        """
        mrbts = self.get_bts_instance_id(bts_id=gnb_id, du_id=du_id)
        nrbts = self.get_global_bts_id(bts_id=gnb_id, du_id=du_id)

        return self._get_object_parameters_dict(
            dist_name="MRBTS-{}/NRBTS-{}".format(mrbts, nrbts), bts_id=gnb_id, du_id=du_id)['gNbCuType']

    @login_logout
    def lock_gnb(self, gnb_id=0, du_id=0):
        """
        Lock gNB
        :param gnb_id:      gnb_id: gNB id - related to Test Line configuration.
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:    None
        """
        dist_name = self._get_runtime_du_dist_name(gnb_id=gnb_id, du_id=du_id)
        self.admin.lock(dist_name=dist_name, connection=self.rest_alias.format(gnb_id, du_id))

    @login_logout
    def unlock_gnb(self, gnb_id=0, du_id=0):
        """
        Unlock gNB
        :param gnb_id:      gnb_id: gNB id - related to Test Line configuration.
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:    None
        """
        dist_name = self._get_runtime_du_dist_name(gnb_id=gnb_id, du_id=du_id)
        self.admin.unlock(dist_name=dist_name, connection=self.rest_alias.format(gnb_id, du_id))

    def _get_runtime_du_dist_name(self, gnb_id=0, du_id=0):
        """
        Get runtime DU dist_name
        :param gnb_id:      gnb_id: gNB id - related to Test Line configuration.
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:            runtime dist_name
        """
        bts_info = self.admin.get_bts_info(connection=self.rest_alias.format(gnb_id, du_id))
        dist_name = next((du['id']['internal'] for du in bts_info['nrDU'] if du['gNbDuId'] == du_id))
        if dist_name is None:
            raise DataNotAvailable('Status for {0} not found'.format(self.rest_alias.format(gnb_id, du_id)))
        return dist_name

    def verify_gnb_is_locked(self, gnb_id=0, du_id=0):
        """
        Verify if gNB administrative state is locked
        :param gnb_id:      gnb_id: gNB id - related to Test Line configuration.
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """
        administrative_state = self._get_gnb_administrative_state(gnb_id, du_id)
        if administrative_state != 'Locked':
            raise IncorrectParameterValue(
                "DU{0} administrative state is {1}, but should be locked".format(du_id, administrative_state))

    def verify_gnb_is_unlocked(self, gnb_id=0, du_id=0):
        """
        Verify if gNB administrative state is unlocked
        :param gnb_id:      gnb_id: gNB id - related to Test Line configuration.
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """
        administrative_state = self._get_gnb_administrative_state(gnb_id, du_id)
        if administrative_state != 'Unlocked':
            raise IncorrectParameterValue(
                "DU{0} administrative state is {1}, but should be unlocked".format(du_id, administrative_state))

    @login_logout
    def _get_gnb_administrative_state(self, gnb_id=0, du_id=0):
        bts_info = self.admin.get_bts_info(connection=self.rest_alias.format(gnb_id, du_id))
        gnb_status = next((du['status']['administrativeState'] for du in bts_info['nrDU'] if du['gNbDuId'] == du_id))
        if gnb_status is None:
            raise DataNotAvailable('Status for {0} not found'.format(self.rest_alias.format(gnb_id, du_id)))
        return gnb_status

    @login_logout
    def set_bts_rad_parameters(self, component, params, bts_id=0, wait_for_reconnection=True, du_id=0):
        """
        Set R&D parameters on WebEM using API.

        .. note::
            SUPPORTS INTERNAL API ONLY
        :param Union[int,str] component: BTS system component number, eg. 25 (OAM domain id 0X19)
        :param string params: RAD parameters string (parameter:value,...) eg. 210:5
        :param bts_id:int, BTS id - related to Test Line configuration.
        :param wait_for_reconnection:bool, flag which define if admin api will wait for reconnection to bts.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return Union[str, dict]: Value of status parameter of BTS_SERVICE_PROCEDURE object

        More details: https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-setRadParam.html
        """
        connection = self.rest_alias.format(bts_id, du_id)
        self.admin.change_bts_rad_parameters_permanently(component=to_int(component), params=params,
                                                         connection=connection)

    @login_logout
    def get_bts_rad_parameters(self, parameters_type, bts_id=0, wait_for_reconnection=True, du_id=0):
        """
        Get R&D parameters from SW config using API.

        .. note::
        SUPPORTS INTERNAL API ONLY
        :param string parameters_type: Requested (SW Config, present in file) or Applied (SW Config +
            changes made during runtime)
        :param bts_id:int, BTS id - related to Test Line configuration.
        :param wait_for_reconnection:bool, flag which define if admin api will wait for reconnection to bts.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return list: List of dicts containing flag:value pairs.

        More details: https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-getRadParameters.html
        """
        connection = self.rest_alias.format(bts_id, du_id)
        self.admin.get_bts_rad_parameters(parameters_type=parameters_type, connection=connection)

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def set_rad_parameter_value(self, parameter, value, gnb_id=0, du_id=0):
        """
        Set R&D parameter value on FPGA module, eg. Loki.

        :param parameter:   R&D parameter, eg. link_meas_window_len
        :param value:       Value of a given R&D parameter
        :param gnb_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """
        try:
            gnb = DeviceFactory.get_device(name=self.ssh_alias.format(gnb_id, du_id))
            gnb.goto_state("FSP")
            write_cmd = gnb.get_cmd(cmd_name="confmgmtbrowser",
                                    cmd_params={'mode': 'write', 'parameter': parameter, 'value': value})
            write_cmd()
            MolerTest.steps_end()
        except DeviceChangeStateFailure as err:
            MolerTest.error("Couldn't correctly establish connection to FST BTS\n{}".format(repr(err)))
            MolerTest.steps_end()

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def get_rad_parameter_value(self, parameter, gnb_id=0, du_id=0):
        """
        Get value of R&D parameter from FPGA module, eg. Loki.

        :param parameter    R&D parameter, eg. link_meas_window_len
        :param gnb_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return dict:       Dict containing domain, key and value of parameter.
        """
        try:
            gnb = DeviceFactory.get_device(name=self.ssh_alias.format(gnb_id, du_id))
            gnb.goto_state("FSP")
            read_cmd = gnb.get_cmd(cmd_name="confmgmtbrowser", cmd_params={'mode': 'read', 'parameter': parameter})
            MolerTest.steps_end()
            get_cmd_output = read_cmd()
            return get_cmd_output
        except DeviceChangeStateFailure as err:
            MolerTest.error("Couldn't correctly establish connection to FST BTS\n{}".format(repr(err)))
            MolerTest.steps_end()
